-- MOBILEData V4 - BO DU LIEU MAU TUONG THICH SCHEMA 23/11/2026

-- KHONG CHAY NEU CHUA SAO LUU. Chu y du lieu gia lap, khong phai thue bao/CCCD that.

-- Script all-or-nothing (transaction). Chay 1 lan, lan hai se tu choi de tranh nhan doi.

-- Chi INSERT du lieu mau, KHONG DELETE/UPDATE du lieu cu.

USE [MobileDataDB];
GO
SET NOCOUNT ON;
SET XACT_ABORT ON;

IF OBJECT_ID(N'dbo.KhachHang',N'U') IS NULL OR OBJECT_ID(N'dbo.TinNhanHoTro',N'U') IS NULL
    THROW 51001, N'Schema khong du 10 bang. Can dung schema hien tai.', 1;

BEGIN TRY
  BEGIN TRANSACTION;

  IF EXISTS (SELECT 1 FROM dbo.KhachHang WHERE CCCD BETWEEN '999900000001' AND '999900000030')
      THROW 51002, N'Da co du lieu demo voi CCCD 99990000xxxx; khong nhap trung.', 1;

  IF EXISTS (SELECT 1 FROM dbo.ThueBao WHERE SoDienThoai IN (N'0398000001',N'0918000002',N'0908000003',N'0398000004',N'0918000005',N'0908000006',N'0398000007',N'0918000008',N'0908000009',N'0398000010',N'0918000011',N'0908000012',N'0398000013',N'0918000014',N'0908000015',N'0398000016',N'0918000017',N'0908000018',N'0398000019',N'0918000020',N'0908000021',N'0398000022',N'0918000023',N'0908000024',N'0398000025',N'0918000026',N'0908000027',N'0398000028',N'0918000029',N'0908000030',N'0918000101',N'0908000102',N'0398000103',N'0918000104',N'0908000105',N'0398000106',N'0918000107',N'0908000108',N'0398000109',N'0918000110'))
      THROW 51003, N'So dien thoai demo da duoc su dung; da dung de tranh ghi de.', 1;

  IF EXISTS (SELECT 1 FROM dbo.GoiCuoc WHERE MaGoiHienThi LIKE 'MDVT%' OR MaGoiHienThi LIKE 'MDVN%' OR MaGoiHienThi LIKE 'MDMB%')
      THROW 51004, N'Ma goi demo da ton tai; da dung de tranh nhan doi.', 1;

  IF NOT EXISTS(SELECT 1 FROM dbo.NhaMang WHERE MaNhaMang=N'VT')
      INSERT dbo.NhaMang(MaNhaMang,TenNhaMang,DangHoatDong) VALUES(N'VT',N'Viettel',1);

  IF NOT EXISTS(SELECT 1 FROM dbo.NhaMang WHERE MaNhaMang=N'VN')
      INSERT dbo.NhaMang(MaNhaMang,TenNhaMang,DangHoatDong) VALUES(N'VN',N'VinaPhone',1);

  IF NOT EXISTS(SELECT 1 FROM dbo.NhaMang WHERE MaNhaMang=N'MB')
      INSERT dbo.NhaMang(MaNhaMang,TenNhaMang,DangHoatDong) VALUES(N'MB',N'MobiFone',1);

  CREATE TABLE #DemoCustomers(CCCD VARCHAR(12), HoTen NVARCHAR(100), GioiTinh NVARCHAR(12), NamSinh SMALLINT, QueQuan NVARCHAR(120), DiaChi NVARCHAR(200), Email VARCHAR(150));



  INSERT dbo.KhachHang(CCCD,HoTen,GioiTinh,NamSinh,QueQuan,DiaChi,Email,NgayTao)
  SELECT CCCD,HoTen,GioiTinh,NamSinh,QueQuan,DiaChi,Email,CONVERT(DATETIME2(0),'2025-03-01T09:00:00') FROM #DemoCustomers;

  IF @@ROWCOUNT<>30 THROW 51005, N'Khong tao du 30 khach hang.', 1;

  CREATE TABLE #DemoSubs(CCCD VARCHAR(12), Carrier VARCHAR(5), Phone VARCHAR(10), Created DATETIME2(0), State VARCHAR(12), Balance DECIMAL(18,0));



  INSERT dbo.ThueBao(MaKhachHang,MaNhaMang,SoDienThoai,SoDu,TrangThai,NgayTao)
  SELECT kh.MaKhachHang,s.Carrier,s.Phone,s.Balance,s.State,s.Created FROM #DemoSubs s JOIN dbo.KhachHang kh ON kh.CCCD=s.CCCD;

  IF @@ROWCOUNT<>40 THROW 51006, N'Khong tao du 40 thue bao.', 1;

  INSERT dbo.TaiKhoan(MaThueBao,VaiTro,DangHoatDong,NgayTao)
  SELECT tb.MaThueBao, CASE WHEN s.Phone=N'0398000001' THEN 'ADMIN' ELSE 'USER' END, 1, s.Created
  FROM #DemoSubs s JOIN dbo.ThueBao tb ON tb.SoDienThoai=s.Phone;

  IF @@ROWCOUNT<>40 THROW 51007, N'Khong tao du 40 tai khoan.', 1;

  CREATE TABLE #DemoPlans(Carrier VARCHAR(5), Code VARCHAR(20), Name NVARCHAR(100), Price DECIMAL(18,0), DataGb DECIMAL(10,2), DataMode VARCHAR(10), Days INT, Description NVARCHAR(500), Popular BIT, Selling BIT);



  INSERT dbo.GoiCuoc(MaNhaMang,MaGoiHienThi,TenGoi,Gia,DungLuongGB,KieuDungLuong,ChuKyNgay,MoTa,PhoBien,DangBan)
  SELECT Carrier,Code,Name,Price,DataGb,DataMode,Days,Description,Popular,Selling FROM #DemoPlans;

  IF @@ROWCOUNT<>36 THROW 51008, N'Khong tao du 36 goi cuoc.', 1;

  CREATE TABLE #DemoRegs(Phone VARCHAR(10), Code VARCHAR(20), Started DATETIME2(0), Ended DATETIME2(0), Canceled DATETIME2(0) NULL, State VARCHAR(12), Price DECIMAL(18,0), Gb DECIMAL(10,2), DataMode VARCHAR(10), Days INT);



  INSERT dbo.DangKyGoi(MaThueBao,MaGoi,GiaLucDangKy,DungLuongGBLucDangKy,KieuDungLuongLucDangKy,ChuKyNgayLucDangKy,NgayDangKy,NgayHetHan,NgayHuy,TrangThai)
  SELECT tb.MaThueBao,goi.MaGoi,r.Price,r.Gb,r.DataMode,r.Days,r.Started,r.Ended,r.Canceled,r.State
  FROM #DemoRegs r JOIN dbo.ThueBao tb ON tb.SoDienThoai=r.Phone JOIN dbo.GoiCuoc goi ON goi.MaGoiHienThi=r.Code AND goi.MaNhaMang=tb.MaNhaMang;

  IF @@ROWCOUNT<>160 THROW 51009, N'Khong tao du 160 lich su dang ky.', 1;

  CREATE TABLE #DemoTransactions(Phone VARCHAR(10), Code VARCHAR(20) NULL, Started DATETIME2(0) NULL, Kind VARCHAR(20), Amount DECIMAL(18,0), State VARCHAR(10), Note NVARCHAR(300), At DATETIME2(0));



  INSERT dbo.GiaoDich(MaThueBao,MaDangKy,LoaiGiaoDich,SoTien,TrangThai,GhiChu,NgayGiaoDich)
  SELECT tb.MaThueBao,dk.MaDangKy,t.Kind,t.Amount,t.State,t.Note,t.At
  FROM #DemoTransactions t JOIN dbo.ThueBao tb ON tb.SoDienThoai=t.Phone
  LEFT JOIN dbo.GoiCuoc g ON g.MaGoiHienThi=t.Code AND g.MaNhaMang=tb.MaNhaMang
  LEFT JOIN dbo.DangKyGoi dk ON dk.MaThueBao=tb.MaThueBao AND dk.MaGoi=g.MaGoi AND dk.NgayDangKy=t.Started;

  IF @@ROWCOUNT<>285 THROW 51010, N'Khong tao du 285 giao dich.', 1;

  CREATE TABLE #DemoTickets(Ref INT, Phone VARCHAR(10), Title NVARCHAR(160), State VARCHAR(12), Created DATETIME2(0), Updated DATETIME2(0));



  INSERT dbo.YeuCauHoTro(MaThueBao,TieuDe,TrangThai,NgayTao,NgayCapNhat)
  SELECT tb.MaThueBao,t.Title,t.State,t.Created,t.Updated FROM #DemoTickets t JOIN dbo.ThueBao tb ON tb.SoDienThoai=t.Phone;

  IF @@ROWCOUNT<>24 THROW 51011, N'Khong tao du 24 yeu cau ho tro.', 1;

  CREATE TABLE #DemoMsgs(Ref INT, Sender VARCHAR(5), Message NVARCHAR(2000), At DATETIME2(0));



  DECLARE @AdminAccountId INT = (SELECT tk.MaTaiKhoan FROM dbo.TaiKhoan tk JOIN dbo.ThueBao tb ON tb.MaThueBao=tk.MaThueBao WHERE tb.SoDienThoai=N'0398000001' AND tk.VaiTro='ADMIN');

  IF @AdminAccountId IS NULL THROW 51012, N'Khong tim thay tai khoan ADMIN demo.', 1;

  INSERT dbo.TinNhanHoTro(MaYeuCau,MaTaiKhoan,VaiTroNguoiGui,NoiDung,NgayGui)
  SELECT y.MaYeuCau,CASE WHEN m.Sender='ADMIN' THEN @AdminAccountId ELSE tk.MaTaiKhoan END,m.Sender,m.Message,m.At
  FROM #DemoMsgs m JOIN #DemoTickets d ON d.Ref=m.Ref
  JOIN dbo.ThueBao tb ON tb.SoDienThoai=d.Phone
  JOIN dbo.YeuCauHoTro y ON y.MaThueBao=tb.MaThueBao AND y.TieuDe=d.Title AND y.NgayTao=d.Created
  JOIN dbo.TaiKhoan tk ON tk.MaThueBao=tb.MaThueBao;

  IF @@ROWCOUNT<40 THROW 51013, N'Khong tao du tin nhan ho tro.', 1;

  COMMIT TRANSACTION;

  PRINT N'Đã thêm bộ dữ liệu mẫu thành công. Hai số đăng nhập: ADMIN 0398000001 (VT), USER 0918000002 (VN).';

END TRY
BEGIN CATCH
 IF @@TRANCOUNT>0 ROLLBACK TRANSACTION;
 THROW;
END CATCH;

GO
SELECT MaNhaMang, TenNhaMang FROM dbo.NhaMang;
SELECT COUNT(*) AS TongKhachHang FROM dbo.KhachHang;
SELECT COUNT(*) AS TongGiaoDich FROM dbo.GiaoDich;
